from pathlib import Path
import json, subprocess, html
R=Path(__file__).resolve().parents[1];D=json.loads((R/'play/data.json').read_text())
fraw=subprocess.check_output(['node','-e',"const f=require('./play/figures.js'); console.log(JSON.stringify({tower:f.icon('tower'),sign:f.icon('sign'),roof:f.icon('roof'),river:f.river({rotation:1,mirror:true}),riverCanonical:f.river({rotation:0,mirror:false}),parkA:f.park({rotation:3,mirror:true}),parkB:f.park({rotation:3,mirror:false}),facade:f.facade(),scene:f.scene()}))"],cwd=R,text=True)
F=json.loads(fraw)
def esc(x):return html.escape(str(x))
def text(x,lang):return x.get(lang,x.get('zh','')) if isinstance(x,dict) else str(x)
def page(title,body,sub='',cls=''):
 return f'<section class="page {cls}"><header><span>SCENE EXPRESS · R3.1</span><span>ORIGINAL GAME MATERIAL / NO VENUE AFFILIATION</span></header><h1>{title}</h1><p class="sub">{sub}</p>{body}</section>'
def field_table(fs,l):
 return '<table><tbody>'+''.join('<tr><th>'+esc(text(f['label'],l))+'</th><td>'+ '<br>'.join('□ '+esc(text(label,l)) for v,label in f['options'])+'</td></tr>' for f in fs)+'</tbody></table>'
style='''@page{size:A4;margin:14mm 16mm 14mm}*{box-sizing:border-box}body{font:11pt/1.48 "Noto Sans CJK SC",Arial,sans-serif;color:#203441;margin:0}.page{break-after:page;min-height:258mm}.page:last-child{break-after:auto}header{display:flex;justify-content:space-between;gap:10mm;border-bottom:1.5pt solid #203441;font-size:7pt;letter-spacing:.07em;padding-bottom:3mm}h1{font-size:23pt;line-height:1.2;margin:7mm 0 3mm}h2{font-size:14pt;margin:5mm 0 2mm}h3{font-size:11pt}.sub{font-size:8.5pt;color:#566875}p{margin:2.5mm 0 3.5mm}.callout{border:2pt double #203441;padding:5mm;margin:4mm 0}.cards{display:flex;gap:3mm;align-items:stretch}.card{flex:1;border:1px dashed #627781;padding:3mm;text-align:center;break-inside:avoid}.card svg{width:100%;height:46mm}.caption{font-size:8pt}.diagram{width:87mm;margin:4mm auto}.diagram svg{width:100%;height:auto}.wide svg{width:100%;height:auto}.half{display:flex;gap:5mm}.half>div{width:50%}.half svg{width:100%}.cutline{border-top:1px dashed #687986;margin:4mm 0}.strip{border:1px dashed #687986;padding:4mm;margin:3mm 0}.track{height:16mm;border:1px solid #687986;margin:3mm 0;padding:4mm}.quiet{font-size:8pt;color:#596b75}table{width:100%;border-collapse:collapse;margin:3mm 0;font-size:9.5pt}th,td{border:1px solid #bac6c8;padding:2.8mm;vertical-align:top;text-align:left}th{width:38%;font-weight:600;background:#f0f2ef}.sign{font-size:22pt;text-align:center;border:2px solid #203441;padding:4mm;letter-spacing:.1em}.source{font-size:8pt;overflow-wrap:anywhere;margin-bottom:4mm}.write{height:12mm;border-bottom:1px solid #617780}.no-print{background:#eef2ed;padding:10px;font-size:14px}@media print{.no-print{display:none}}'''
for l in ['zh','en']:
 T=lambda z,e:z if l=='zh' else e
 pages=[]
 pages.append(page(esc(text(D['title'],l)),f'<div class="callout"><p>{esc(text(D["opening"],l))}</p></div><h2>{T("原件请帖","The original invitation")}</h2><div class="sign">千歳座 · CHITOSE-ZA</div><p>{T("收件人：千歳座的今日继承者。景名：稲瀬川百本杭。请把河边开始的那场戏，送到它今天的名字下面。","Addressee: the present identity descended from Chitose-za. Scenery: Inase River and its piles. Bring the riverside beginning of the theatre to its present name.")}</p><h2>{T("三类信息，先分清来源","Three kinds of information")}</h2><table><tr><th>ORIGINAL</th><td>{T("伊都交付的原件。双线框。","Ito’s original commission: double-line frame.")}</td></tr><tr><th>REN</th><td>{T("对手的解释，不是馆方结论。斜线框。","Ren’s interpretation, not a venue statement: hatched frame.")}</td></tr><tr><th>FIELD SOURCE</th><td>{T("现场观察或附来源的独立摘要。","Site observation or a sourced factual summary.")}</td></tr></table><p>{esc(text(D["safety"],l))}</p><h2>{T("小组名／日期／记录模式","Team / date / mode")}</h2><div class="write"></div><p class="quiet">{T("桌面试玩与实地试玩请分开记录。所有人物及竞赛为虚构。","Record desktop and field tests separately. Characters and competition are fictional.")}</p>'))
 q=D['stages'][0]
 cards=''.join(f'<div class="card"><b>{esc(text(c["label"],l))}</b>{F[c["icon"]]}<p class="caption">{T("对照现场，不补猜被遮挡文字","Compare on site; do not invent hidden text")}</p></div>' for c in q['cards'])
 pages.append(page(esc(text(q['title'],l)),f'<p>{esc(text(q["intro"],l))}</p><div class="cards">{cards}</div><h2>{T("在纸框中复原连续视野","Restore the continuous view")}</h2><div class="track">[________________] → [________________] → [________________]</div>{field_table(q["fields"],l)}<p class="quiet">{T("插图是按用户实拍所绘的功能识别图，不是新的现场照片。无需进入博物馆。","These are functional recognition sketches from the supplied field evidence, not new site photographs. No museum entry is required.")}</p><div class="write"></div>'))
 pieces=[]
 for c in q['cards']:
  x={'tower':0,'sign':200,'roof':400}[c['id']]
  inner=F['scene'].split('>',1)[1].rsplit('</svg>',1)[0]
  img=f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{x} 0 200 180">{inner}</svg>'
  pieces.append(f'<div class="card"><b>{esc(text(c["label"],l))}</b>{img}</div>')
 pages.append(page(T('01B · 景片底层与装配框','01B · Scenery strips and frame'),'<p>'+T('将下面三段剪下，与对应的街景卡一起使用；按现场复原的视野顺序装入框。片段是原创示意，不是历史版画复制。','Cut these strips and keep each with its corresponding view card. Assemble them in the observed order. The image is an original schematic, not a copied historical print.')+'</p><div class="cards">'+''.join(pieces)+'</div><div class="callout" style="height:68mm">'+T('装配框：连续河景放在这里','FRAME: assemble the continuous river scene here')+'</div><div class="sign">稲瀬川 百本杭<br><small style="font-size:11pt">INASE RIVER / RIVERSIDE PILES</small></div><p>'+T('原件下一对照站：両国橋。莲把上面两个词当作完整地址。你们需要拿这件景片去检验他的说法，而不是先接受导航搜索结果。','Next comparison site on the original: Ryogoku Bridge. Ren treats this caption as a full address. Take this scene to test his claim rather than accepting a search result as proof.')+'</p>'))
 q=D['stages'][1]
 pages.append(page(esc(text(q['title'],l)),f'<p>{esc(text(q["intro"],l))}</p><div class="diagram">{F["river"]}</div><p class="quiet">{T("可旋转纸卡。要翻面时，对照下一页提供的另一面；它们不是两条不同的河。","Rotate the card. To simulate turning it over on opaque paper, use the alternate face on the next page; these are not different rivers.")}</p>{field_table(q["fields"],l)}'))
 pages.append(page(T('02B · 河图另一面与来源卡','02B · Alternate face and source card'),f'<div class="diagram">{F["riverCanonical"]}</div><div class="half"><div class="strip">STAGE NAME<br>稲瀬川 / INASE<br>________________</div><div class="strip">REAL SCENERY<br>隅田川 / SUMIDA<br>________________</div></div><h2>{T("实地资料 R02","Field source R02")}</h2><p>{esc(text(D["sources"][1]["fact"],l))}</p><p class="quiet">{T("这项事实可免费查阅。题目是如何使用它，而不是凭日文记忆猜答案。旧桥位置只是象征，不测米数。","This fact is available without penalty. The task is its interpretation, not recall of Japanese. The old bridge line is symbolic, not a measurement.")}</p><div class="strip">REN: '+T('“景名在镰仓，收件人就必然也在镰仓。”','“If the scene is named after a river in Kamakura, the addressee must be in Kamakura too.”')+'</div><p>'+T('交接：下一张旅人取景记录指向芭蕉免费区域。另有REN的便签称其为1930原始摄影，请保留便签来源。','Handoff: the traveller-view record points to the free Basho area. A separate REN note claims it is an original photograph from 1930. Keep the attribution visible.')+'</p>'))
 q=D['stages'][2]
 pages.append(page(esc(text(q['title'],l)),f'<p>{esc(text(q["intro"],l))}</p><div class="strip">REN: ORIGINAL PHOTOGRAPH — 1930</div><div class="track">{T("人物生活轨道","Person’s life")}: ______________</div><div class="track">{T("题图设施摄影下界","Earliest possible photograph of the setting")}: ______________</div>{field_table(q["fields"],l)}<p class="quiet">{T("平成七年＝1995。纪念古人的设施不是古人生活时已经存在的同一件实物。","Heisei 7 = 1995. A memorial to an old figure is not an object from that figure’s lifetime.")}</p><div class="strip">□ '+T('公开驳回：独立校正下一张图','Challenge: orient the next tracing independently')+'<br>□ '+T('交换来源：得到大锚点校正提示，仍需判断相机侧','Exchange sources: receive large-anchor help; still determine the camera side')+'</div>'))
 q=D['stages'][3]
 pages.append(page(esc(text(q['title'],l)),f'<p>{esc(text(q["intro"],l))}</p><div class="wide">{F["facade"]}</div><p class="quiet">{T("按现场照片转为功能图：前景是游乐设施，后景是菱形外墙。它不是体育馆新建年份证明。","Functional drawing based on the field photograph: play equipment in front, diamond facade behind. This does not establish a construction date.")}</p>{field_table(q["fields"],l)}'))
 pages.append(page(T('04B · 描图纸的两面','04B · Two faces of the tracing'),'<p>'+T('A、B剪下背靠背夹起即可模拟翻面，无需透明材料；先对照真实案内图，旋转到三处大锚点同时吻合。所示为相对布局，不是以北为固定上方的导航地图。','Cut A and B and clip them back-to-back; no transparency material is required. Rotate to match three anchors on the real map. This is relative layout, not a north-up navigation map.')+'</p><div class="half"><div><b>FACE A</b>'+F['parkA']+'</div><div><b>FACE B</b>'+F['parkB']+'</div></div><div class="half"><div class="strip">CAPTURE AT<br>'+T('取景定位','View location')+'</div><div class="strip">DELIVER TO<br>'+T('收件地址','Recipient address')+'</div></div><h2>'+T('相机位置片（选择一个）','Camera markers (choose one)')+'</h2><div class="half"><div class="strip">PLAYGROUND<br>游乐区</div><div class="strip">ENTRANCE<br>圆形入口</div></div><div class="half"><div class="strip">RIVER EDGE<br>河侧</div><div class="strip">FIELD<br>大场地侧</div></div><p class="quiet">'+T('不能沿图进入运动场、体育中心或围挡；只从允许通行处核对可见关系。','Never follow this diagram into the field, centre or barriers. Compare visible relationships from permitted paths only.')+'</p>'))
 q=D['stages'][4]
 strips=''.join('<div class="strip">'+esc(text(c['label'],l))+'</div>' for c in q['cards'])
 pages.append(page(esc(text(q['title'],l)),f'<p>{esc(text(q["intro"],l))}</p>{strips}<div class="strip">1928 · '+T('迁到今浜町公园附近后重新开场','Reopened near present-day Hamacho Park')+'</div><p>'+T('拼合名字链，再将迁址条归入位置栏。对照今天的外部招牌，不进入剧场。','Build the name chain, then place the move under location history. Check the exterior sign; do not enter the theatre.')+'</p>'+field_table(q['fields'],l)))
 pages.append(page(T('终局 · 签收前的七项核对','FINAL · Seven checks before signing'),'<p>'+T('把前五站得到的证据填在一起。名字提前猜对也允许，但不能将错误的景、时间和用途一起寄出。','Combine the evidence from all five stops. Guessing the name early is allowed, but the scenery, time and purpose must still agree.')+'</p>'+field_table(D['finalFields'],l)+'<div class="strip">□ '+T('独立签收','Independent delivery')+'　□ '+T('联合签收','Joint delivery')+'</div><div class="write"></div><p class="quiet">'+T('签收对象为虚构送景社，不是现场任何商家。此纸不是入场券。','The receiving authority is the fictional Scene Express host, not a real business. This is not an admission ticket.')+'</p>'))
 pages.append(page(T('回执与纪念景片','RECEIPT & SCENE CARD'),'<div class="wide">'+F['scene']+'</div><div class="callout"><h2>SCENE EXPRESS</h2><p>STAGE NAME: ____________________</p><p>REAL SCENERY: ___________________</p><p>REFERENCE DATE CLASS: ____________</p><p>OLD NAME → PRESENT IDENTITY: __________________</p><p>CAPTURE LOCATION / PURPOSE: ___________________</p><p>TEAM / OUTCOME: _____________________________</p></div><p>'+T('沿虚线裁成可折叠明信片，正面保留景，背面写下正确回执。不是把旧名字擦掉，而是让每个名字留在该在的位置。','Cut and fold into a postcard. Retain the scene on the front and the justified receipt on the back. Do not erase the historical names; keep them in the correct fields.')+'</p><div class="cutline"></div><p class="quiet">'+T('原型纪念样张，非商业终版插画。图形为自有功能示意，未复制第三方馆藏图。','Prototype souvenir, not final commercial illustration. Original functional graphics; no third-party collection image is reproduced.')+'</p>'))
 facts=''.join(f'<div class="source"><b>{esc(s["id"])} · {esc(s["title"])}</b><br>{esc(text(s["fact"],l))}<br>{esc(s["url"])}</div>' for s in D['sources'])
 cut=facts.find('<div class="source"><b>M01')
 for j,body in enumerate([facts[:cut],facts[cut:]]):pages.append(page(T('实地资料与来源','FIELD FACTS & SOURCES')+f' · {j+1}',body))
 doc=f'<!doctype html><html lang="{l}"><head><meta charset="utf-8"><title>Scene Express R3.1 Player Kit {l}</title><style>{style}</style></head><body><div class="no-print">Print at 100% / A4. <button onclick="window.print()">Print</button></div>'+''.join(pages)+'</body></html>'
 (R/f'play/print_{l}.html').write_text(doc,'utf8')
(R/'play/print.html').write_text('<!doctype html><meta charset="utf-8"><title>Print kit</title><h1>R3.1 Print kit</h1><p><a href="print_zh.html">中文</a></p><p><a href="print_en.html">English</a></p><p>A4 / 100% / no duplex registration required.</p>','utf8')
app=(R/'play/index.html').read_text()
app=app.replace('<link rel="stylesheet" href="style.css">','<style>'+(R/'play/style.css').read_text()+'</style>')
for name in ['data.js','engine.js','figures.js','app.js']:
 app=app.replace(f'<script src="{name}"></script>','<script>'+(R/f'play/{name}').read_text().replace('</script','<\\/script')+'</script>')
app=app.replace('href="print.html"','href="play/print.html"')
(R/'R3_Offline.html').write_text(app,'utf8')
print('Created',len(pages),'player pages per language; standalone app bundled.')
